//! The saarthi wire format: protobuf definitions under `proto/`, generated by prost and tonic.
//! The Android client generates Kotlin from the same files.

pub mod event {
    pub mod v1 {
        tonic::include_proto!("saarthi.event.v1");
    }
}

pub mod node {
    pub mod v1 {
        tonic::include_proto!("saarthi.node.v1");
    }
}

pub mod control {
    pub mod v1 {
        tonic::include_proto!("saarthi.control.v1");
    }
}
